import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { ContractError, type NomosBlock, TurnCheck } from "../src/contract.ts";

// Generated by the actual Python serve at the merged Plan 2 revision, using
// its CPU fake engines. This fixture does not import the TS fake producer.
const fixture = JSON.parse(readFileSync(new URL("fixtures/serve-5e4a100.json", import.meta.url), "utf8"));

test("cross-plan: every built serve fixture satisfies TurnCheck, including off-mode and refused workspace rows", () => {
  assert.equal(fixture.kernel_commit, "5e4a100c137bc01b42ba44c2cde473ad435711c0");
  assert.equal(fixture.cases.length, 13);
  for (const { name, block, chunks } of fixture.cases) {
    const check = new TurnCheck(block);
    const updates = chunks.flatMap((c: unknown) => check.take(c) ?? []);
    const summary = check.close(chunks[0].id);
    assert.deepEqual(summary, chunks.at(-1).nomos.summary, name);
    const records = updates.flatMap((u: { records: unknown[] }) => u.records);
    assert.equal(records.length, summary.counts.records, name);
    if (name.includes("workspace-unavailable")) {
      assert.ok(records.some((r: any) => r.source === "generated" && r.workspace === null && r.missing.includes("workspace_unavailable")));
      assert.equal(summary.counts.workspace_valid, 0);
    }
  }
});

test("cross-plan: the real GPU e2e's summary-only response validates without invented records", () => {
  const summary = fixture.real_e2e.turn5_steer_only;
  const { from_pos, ...steer } = summary.header.steer;
  const block: NomosBlock = { conversation: "e2e", turn: 4, steer };
  const check = new TurnCheck(block);
  check.take({ id: summary.header.response_id, nomos: { summary } });
  assert.deepEqual(check.close(summary.header.response_id), summary);
  for (const name of ["turn1_all", "turn2_new"]) {
    const turn = fixture.real_e2e[name];
    assert.equal(turn.prompt[1], turn.generated[0]);
    assert.equal(turn.missing.kv_reused, turn.prompt[0]);
    assert.equal(turn.records, turn.generated[1] - turn.prompt[0]);
  }
});

test("cross-plan: a mismatched ordinary completion ID and an incorrect reused count refuse producer fixtures", () => {
  for (const fault of ["id", "reused"]) {
    const item = structuredClone(fixture.cases.find((c: any) => c.name === "spec-reuse"));
    if (fault === "id") item.chunks[0].id = "another-completion";
    else item.chunks.at(-1).nomos.summary.missing.kv_reused++;
    const check = new TurnCheck(item.block);
    assert.throws(() => item.chunks.forEach((c: unknown) => check.take(c)), ContractError);
  }
});
